INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_item_category_platform_metrics_1d
PARTITION (
    grass_region=${grass_region},
    local_date=${local_date}
)
SELECT 
    a.exp_group_id
    ,a.experiment_id
    ,a.platform
    ,a.level1_global_be_category_id
    ,a.level2_global_be_category_id
    ,a.level1_global_be_category
    ,a.level2_global_be_category

    ,imp_cnt
    ,imp_uu
    ,click_cnt 
    ,order_cnt 
    ,gmv 
    ,pc2_gmv 
    ,search_vol
    ,search_success_vol
    ,revenue_usd AS ads_revenue_usd
FROM 
    dws_exp_search_${grass_region_without_quote} a
    LEFT JOIN dws_exp_vol_${grass_region_without_quote} b
        ON a.exp_group_id = b.exp_group_id
        AND a.platform = b.platform 
        AND a.level1_global_be_category = '__ALL__'
        AND a.level2_global_be_category = '__ALL__'
    LEFT JOIN exp_ads_performance_${grass_region_without_quote} c 
        ON a.exp_group_id = c.exp_group_id
        AND a.platform = c.platform 
        AND a.level1_global_be_category_id = c.level1_global_be_category_id
        AND a.level2_global_be_category_id = c.level2_global_be_category_id;
